import{_ as n,l as i,o as l,c as s,v as d,p as E,x as t,d as r,i as p,S as c,b as e}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"线性模型的召回瓶颈","description":"","frontmatter":{"title":"线性模型的召回瓶颈","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/linear-recall-bottleneck.md","filePath":"llm/linear-recall-bottleneck.md","lastUpdated":1789023840000}'),h={name:"llm/linear-recall-bottleneck.md"};function m(A,a,B,u,f,b){const o=i("Mermaid");return l(),s("div",null,[a[1]||(a[1]=d('<h1 id="线性模型的召回瓶颈" tabindex="-1">线性模型的召回瓶颈 <a class="header-anchor" href="#线性模型的召回瓶颈" aria-label="Permalink to &quot;线性模型的召回瓶颈&quot;">​</a></h1><div class="epigraph"><p>固定大小状态是有损压缩；在需要精确拷贝远距 token 的基准上，纯线性混合会系统性失败，除非插入真正的内容寻址。</p><footer>—— Arora et al., Simple Linear Attention Language Models Balance the Recall-Throughput Tradeoff, 2024；亦见其对 Zoology 式受控检索任务的分析</footer></div><p><a href="/llm/hybrid-layer-ratio">上一课</a>断言 \\(r=0\\) 不行，没有把「不行」写成可测的缺口。本课补召回瓶颈：在联想检索、MQAR 一类任务上，<a href="/llm/linear-attention">线性注意力</a>、<a href="/llm/selective-scan">选择性扫描</a>、<a href="/llm/long-convolution">长卷积</a> 相对 softmax 的失败模式。下一课把瓶颈量化到状态维 \\(N\\) 对上下文 \\(n\\) 的关系。本课先定性：失败的是<strong>精确身份</strong>，不是困惑度曲线好看就够。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>语言建模困惑度可以被局部统计带得很低，掩盖「一百步前那个随机键对应的值」有没有被记住。受控任务把键值对塞进上下文，要求模型在末尾按键取回值。Softmax 注意力在表还塞得下时几乎完美。线性状态必须把整张表压进 \\(N\\) 维或 \\(d\\times d\\) 矩阵。缺口是承认：<strong>吞吐基准不能替代召回基准</strong>，混合架构的 \\(r\\) 应由召回曲线决定下限。</p><p>Arora 等人用这类任务比较基于线性注意力的模型与注意力，并讨论用少量注意力或改进的线性机制换吞吐。本课取诊断，不把 BASED 型号当词条。</p><p><span class="marginnote">「召回」在这里是上下文内精确取回，不是检索增强生成的语料库召回，也不是医学召回率那个词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构造长度为 \\(n\\) 的序列：若干 \\((k_i,v_i)\\) 散布其中，查询 \\(k^*\\) 出现在末尾，标签是对应 \\(v^*\\)。变化：键是否重复、是否需要同时记住多对、干扰项密度、距离分布。测准确率对 \\(n\\)、对状态维、对是否含一层 softmax。把同一数据上的 LM 困惑度并列，观察两者解耦。</p><p>诊断线性失败：若加大 \\(N\\) 或矩阵状态维，召回上升，则是容量问题；若加大到接近 \\(nd\\) 仍差，则是更新规则问题（加性糊掉、无竞争）。Delta / 少量注意力通常对第一类有帮助，对「任意稀疏同时多对」仍要内容寻址。</p><h3 id="和注意力汇、长度缩放" tabindex="-1">和注意力汇、长度缩放 <a class="header-anchor" href="#和注意力汇、长度缩放" aria-label="Permalink to &quot;和注意力汇、长度缩放&quot;">​</a></h3><p>召回失败有时被误诊为 sink 或温度。把长度缩放、门控调到最优仍失败，且全注意力基线成功，才能归因于压缩。本课实验顺序：先保证 softmax 基线通过，再换线性层。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SSD 对偶已经说明线性模型对应低结构的注意力矩阵，秩受 \\(N\\) 限制。多对精确绑定需要近乎对角、位置特异的权重，满秩才稳。压缩后键碰撞，读出是若干值的线性混合，准确率按碰撞率下降。选择与门控降低噪声写入，改善有效信噪，但<strong>不增加秩的数量级</strong>。</p><p>困惑度对碰撞不敏感：多数 token 不需要那对精确绑定。这就是为何只看 LM loss 会选出过小的 \\(r\\)。</p><p><span class="marginnote">代码补全、多跳问答、长文档指代，是召回瓶颈在真实数据上的投影。受控任务用来定下限，不是用来刷榜。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>受控任务可以做得对注意力过于友好（键随机、值短），从而低估线性模型在有结构键上的表现。反过来，若任务可被统计捷径解决，会高估线性。应用结论时要对齐任务结构。下一课给出 \\(N\\) 对 \\(n\\) 的粗规则，避免只停留在「线性不行」的口号。混合比课的 \\(r\\gt 0\\) 在本课拿到证据。</p>',18)),(l(),E(c,null,{default:t(()=>[p(o,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20Ctx%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E4%B8%AD%E7%9A%84%E9%94%AE%E5%80%BC%E5%AF%B9%22%5D%20--%3E%20Lin%5B%22%E5%9B%BA%E5%AE%9A%E7%8A%B6%E6%80%81%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20Ctx%20--%3E%20Att%5B%22KV%20%E8%A1%A8%E5%86%85%E5%AE%B9%E5%AF%BB%E5%9D%80%22%5D%0A%20%20Lin%20--%3E%20Collide%5B%22%E9%94%AE%E7%A2%B0%E6%92%9E%E3%80%81%E5%80%BC%E6%B7%B7%E5%90%88%22%5D%0A%20%20Att%20--%3E%20Hit%5B%22%E7%B2%BE%E7%A1%AE%E5%8F%96%E5%9B%9E%22%5D%0A%20%20Collide%20--%3E%20Fail%5B%22%E5%8F%AC%E5%9B%9E%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"固定状态把上下文压成有损摘要，精确远距取回会系统性失败。"),e("li",null,"困惑度掩盖该失败；须用受控召回任务与注意力基线对照。"),e("li",null,"加大状态、delta、选择能改善容量与信噪，不把秩提到满 KV 表。"),e("li",null,"混合架构的注意力层是为这条瓶颈预留的内容寻址。"),e("li",null,"出处：Arora et al., 2024。")],-1))])}const x=n(h,[["render",m]]);export{_ as __pageData,x as default};
